INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-well', 'north', 'the-drove-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-seep', 'east', 'the-seep-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drove-mouth', 'door', 'The Drove Mouth', 'A lane leaves the road here between two hedge banks, wide enough for a herd, its floor worn down below the fields on either side by hooves that went up it every spring for longer than anyone counted. A stone at the corner is polished smooth where beasts rubbed past. The road goes on without it.', 0, 0, 'road', 0, -17, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drove-mouth', 'south', 'the-dry-well', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drove-mouth', 'north', 'the-hollow-lane', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hollow-lane', 'door', 'The Hollow Lane', 'The lane has sunk so deep between its banks that the hedges meet overhead, and you walk in a green trench with roots in the walls at the height of your face. It is dim even at noon. The mud in the bottom holds every print that ever went through it.', 0, 0, 'road', 0, -17, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow-lane', 'south', 'the-drove-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow-lane', 'north', 'the-hedge-gap', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hedge-gap', 'door', 'The Hedge Gap', 'A gap in the hedge bank where a gate stood, the posts still there and the gate gone, and through it a field gone back to thorn and thistle. The lane goes on up past it. Something has been through the gap often enough to keep it open.', 0, 0, 'road', 0, -17, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hedge-gap', 'south', 'the-hollow-lane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hedge-gap', 'north', 'the-holly-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-holly-bank', 'door', 'The Holly Bank', 'Holly has taken the bank on one side of the lane and grown up into a dark wall, glossy and armed, so the lane narrows here and leans away from it. Sheep''s wool hangs in the lowest leaves in grey tufts. It has been there a long time.', 0, 0, 'road', 0, -17, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holly-bank', 'south', 'the-hedge-gap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holly-bank', 'north', 'the-drovers-spring', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drovers-spring', 'door', 'The Drover''s Spring', 'Water comes out of the bank at the side of the lane through a lip of cut stone and falls into a trough below, overgrown with cress, brimming and spilling over into the ruts. Every herd that went up this lane stopped here. Every animal that uses it still does.', 0, 0, 'road', 0, -17, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drovers-spring', 'south', 'the-holly-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drovers-spring', 'north', 'the-steep-pitch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-steep-pitch', 'door', 'The Steep Pitch', 'The lane climbs sharply here, the floor turned to bare stone where the earth has washed off it, worn into steps by hooves. The banks fall away lower as you climb. Above, between the hedges, there is more sky than there was.', 0, 0, 'road', 0, -17, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-steep-pitch', 'south', 'the-drovers-spring', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-steep-pitch', 'north', 'the-blackthorn-lane', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-blackthorn-lane', 'door', 'The Blackthorn Lane', 'Blackthorn closes in on both sides, grey and twisted and hung with sloes, the thorns long enough to go through a sleeve. The lane goes through it in a single narrow way. You cannot see far ahead and nothing ahead can see you.', 0, 0, 'road', 0, -17, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blackthorn-lane', 'south', 'the-steep-pitch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blackthorn-lane', 'north', 'the-wall-end', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wall-end', 'door', 'The Wall End', 'The hedges give out and dry-stone walls take over, grey and lichened and leaning, built without mortar out of stones cleared off fields that are not fields any more. A wall ends here in a tumble of stones. Beyond it, open hill.', 0, 0, 'road', 0, -17, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wall-end', 'south', 'the-blackthorn-lane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wall-end', 'north', 'the-high-lane', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-high-lane', 'door', 'The High Lane', 'The lane runs on up between its walls with the land falling away on both sides, and the wind finds you for the first time. Far below, the road, small and grey. Ahead, the tops, bare and long and empty of anything but grass.', 0, 0, 'road', 0, -17, 2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-lane', 'south', 'the-wall-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-lane', 'north', 'the-cattle-stance', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cattle-stance', 'door', 'The Cattle Stance', 'A walled enclosure beside the lane, square and big enough to hold a herd overnight, its gateway on the lane side, its floor gone to coarse grass greener than the hill around it. Drovers slept against the wall. The wall still breaks the wind.', 0, 0, 'road', 0, -17, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cattle-stance', 'south', 'the-high-lane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cattle-stance', 'north', 'the-stony-rise', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-stony-rise', 'door', 'The Stony Rise', 'The walls fall down and stop, and the lane goes on as a green track over stony ground, the stones breaking through the turf in grey backs. Sheep tracks run off it in every direction. Most of them go nowhere.', 0, 0, 'road', 0, -17, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stony-rise', 'south', 'the-cattle-stance', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stony-rise', 'north', 'the-cairn-shoulder', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cairn-shoulder', 'door', 'The Cairn Shoulder', 'A cairn stands on the shoulder of the hill here, a heap of stones higher than a man, each one put there by somebody passing. Some of the stones are new. From beside it you can see the whole length of the road below, and the wood beyond, a dark line along the west.', 0, 0, 'road', 0, -17, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cairn-shoulder', 'south', 'the-stony-rise', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cairn-shoulder', 'north', 'the-bent-thorn', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bent-thorn', 'door', 'The Bent Thorn', 'One hawthorn stands alone on the open hill, bent over by the wind so far that its crown points down the slope like a hand. Its trunk is polished where things have rubbed against it. It is the only shelter for a mile, and it is not much.', 0, 0, 'road', 0, -17, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bent-thorn', 'south', 'the-cairn-shoulder', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bent-thorn', 'north', 'the-sheep-scrape', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sheep-scrape', 'door', 'The Sheep Scrape', 'A hollow under a bank where sheep have lain out of the wind for so long that the ground is bare and dusty and stinks of them, the bank above worn back into a shallow cave. The sheep are gone. Something else lies in it now, by the hair.', 0, 0, 'road', 0, -17, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sheep-scrape', 'south', 'the-bent-thorn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sheep-scrape', 'north', 'the-tops', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tops', 'door', 'The Tops', 'The top of the hill: wide, flat, all grass, the wind going over it without stopping. There is nothing up here at all but the sky, and the grass, and the track going on across it. Every way you look is down.', 0, 0, 'road', 0, -17, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tops', 'south', 'the-sheep-scrape', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tops', 'west', 'the-sheepwalk', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sheepwalk', 'door', 'The Sheepwalk', 'Open grazing over the top of the hill, short grass and moss and the ring-marks of old folds, cropped close by something that is still up here. The track bends west along the brow. The wood is a long dark line below, and getting closer.', 0, 0, 'road', 0, -18, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sheepwalk', 'east', 'the-tops', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sheepwalk', 'west', 'the-dewpond', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dewpond', 'door', 'The Dewpond', 'A round pond lies on the open top where no stream could ever reach, its floor puddled clay that somebody laid and tamped by hand to hold whatever rain and mist would give it. It has held. The water is clear and cold, and the turf all round it is trodden to mud.', 0, 0, 'road', 0, -19, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dewpond', 'east', 'the-sheepwalk', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dewpond', 'west', 'the-shepherds-ruin', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shepherds-ruin', 'door', 'The Shepherd''s Ruin', 'The walls of a hut stand to knee height on the open hill, a doorway in one end, a fireplace in the other with the stones still blackened. No roof, and no shelter in it from anything. Somebody spent a lot of nights up here, a long time ago.', 0, 0, 'road', 0, -20, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shepherds-ruin', 'east', 'the-dewpond', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shepherds-ruin', 'west', 'the-boundary-dyke', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boundary-dyke', 'door', 'The Boundary Dyke', 'A bank and ditch run across the top of the hill dead straight, older than the walls and older than the lane, dug to say where one people''s ground ended and another''s began. Both peoples are long gone. The dyke goes on saying it.', 0, 0, 'road', 0, -21, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-dyke', 'east', 'the-shepherds-ruin', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-dyke', 'west', 'the-west-brow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-west-brow', 'door', 'The West Brow', 'The tops end at a brow, and below it the hill falls away steeply to the wood, so close now that you can see the shape of the crowns. The track goes over the edge. There is no other way down from here that you can see.', 0, 0, 'road', 0, -22, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-west-brow', 'east', 'the-boundary-dyke', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-west-brow', 'south', 'the-brow-path', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-brow-path', 'door', 'The Brow Path', 'The track goes down off the brow in tight turns across the face of the slope, cut into it by feet and hooves, the drop always on the same side. Loose stones go rattling down ahead of you. The wood''s edge comes up to meet you.', 0, 0, 'road', 0, -22, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brow-path', 'north', 'the-west-brow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brow-path', 'south', 'the-scree-turn', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-scree-turn', 'door', 'The Scree Turn', 'A spill of loose stone lies across the path where the hill has let go, and the path picks its way over it on whatever is steadiest. It all moves a little. Below it the slope turns to grass again, then bracken, then trees.', 0, 0, 'road', 0, -22, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-turn', 'north', 'the-brow-path', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-turn', 'south', 'the-bracken-hillside', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bracken-hillside', 'door', 'The Bracken Hillside', 'Bracken covers the lower hill in a sheet, head-high and brown-green, with the path a narrow trough through it. You cannot see over it. Things move in it beside you, and it is hard to say how close.', 0, 0, 'road', 0, -22, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bracken-hillside', 'north', 'the-scree-turn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bracken-hillside', 'south', 'the-first-oaks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-first-oaks', 'door', 'The First Oaks', 'The first trees of the wood stand out on the hillside ahead of the rest, low and broad and bent by the wind off the tops, their roots gripping the slope. Under them the bracken gives way to leaf litter. The light changes.', 0, 0, 'road', 0, -22, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-oaks', 'north', 'the-bracken-hillside', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-oaks', 'south', 'the-wood-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wood-bank', 'door', 'The Wood Bank', 'A great bank runs along the top edge of the wood, built to keep the beasts on the hill out of the trees, with a ditch on the hill side. It has fallen in here, a long time ago, and the path goes over the low place. Everything else has used it too.', 0, 0, 'road', 0, -22, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wood-bank', 'north', 'the-first-oaks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wood-bank', 'south', 'the-hanger', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hanger', 'door', 'The Hanger', 'The wood clings to the steep lower slope, the trees growing out of it at angles and leaning out over the drop, their roots bare where the soil has slipped. The path goes down between them in steps of root. It is quiet under the trees after the wind.', 0, 0, 'road', 0, -22, 2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanger', 'north', 'the-wood-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanger', 'south', 'the-holly-scarp', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-holly-scarp', 'door', 'The Holly Scarp', 'A short rock step in the slope, grown over with holly so dense that the path has to go down through it in a single cut. The leaves catch at everything. At the bottom, the ground levels out and goes soft.', 0, 0, 'road', 0, -22, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holly-scarp', 'north', 'the-hanger', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holly-scarp', 'south', 'the-spring-line-oaks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-spring-line-oaks', 'door', 'The Spring-Line Oaks', 'Where the hill meets the flat, water comes out of the ground in a line of seeps among the oaks, and the floor is wet and green and sucks at your boots. The water runs off downhill into the wood in threads. The trees here are tall.', 0, 0, 'road', 0, -22, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-line-oaks', 'north', 'the-holly-scarp', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-line-oaks', 'south', 'the-wet-margin', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wet-margin', 'door', 'The Wet Margin', 'The ground at the foot of the hill is a margin of mud and moss and standing water, alders and willow growing up out of it. The path goes across it on what is firmest. It is not very firm.', 0, 0, 'road', 0, -22, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-margin', 'north', 'the-spring-line-oaks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-margin', 'west', 'the-seep-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-seep-edge', 'door', 'The Seep Edge', 'The last of the slope, where it runs down into the wood''s floor, wet and dark and shaded. Ahead, under the trees, the cold seep. Behind, if you look up through the canopy, the hill you came down, a long way up.', 0, 0, 'road', 0, -23, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-seep-edge', 'east', 'the-wet-margin', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-seep-edge', 'west', 'the-cold-seep', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moss-path', 'east', 'the-peat-track', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causey-end', 'west', 'the-causey-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-peat-track', 'door', 'The Peat Track', 'A track leaves the hill road here, two wheel ruts in the turf with a strip of grass between, made by carts that came up for peat and went down loaded. It runs east along the foot of the scarp. Nobody has cut peat here in a lifetime.', 0, 0, 'road', 0, 29, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peat-track', 'west', 'the-moss-path', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peat-track', 'east', 'the-under-scarp', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-under-scarp', 'door', 'The Under-Scarp', 'The scarp stands up on your left like a wall, grey rock and heather and hanging birch, and the track runs along the foot of it on the line where the rock meets the moor. Stones lie in the heather, fallen from above. Some of them are recent.', 0, 0, 'road', 0, 30, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-scarp', 'west', 'the-peat-track', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-scarp', 'east', 'the-fallen-crag', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fallen-crag', 'door', 'The Fallen Crag', 'A piece of the scarp the size of a barn has come down across the track at some time and lies broken in the heather, and the track goes round it. In its shadow the ground is damp and the grass is long. Something has made a bed against the rock.', 0, 0, 'road', 0, 31, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-crag', 'west', 'the-under-scarp', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-crag', 'east', 'the-heather-bench', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-heather-bench', 'door', 'The Heather Bench', 'A broad shelf of heather under the scarp, purple-brown and springy, with the track a pale line through it. The wind comes along the face of the scarp and the heather bends to it all one way. Grouse go up from under your feet.', 0, 0, 'road', 0, 32, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heather-bench', 'west', 'the-fallen-crag', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heather-bench', 'east', 'the-turf-stack-ruin', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-turf-stack-ruin', 'door', 'The Turf-Stack Ruin', 'A long low mound beside the track where cut peats were stacked to dry and never collected, gone back to the moor, heathered over and soft. It is the shape of a stack still. Holes go into it at the bottom.', 0, 0, 'road', 0, 33, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turf-stack-ruin', 'west', 'the-heather-bench', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turf-stack-ruin', 'east', 'the-raven-rock', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-raven-rock', 'door', 'The Raven Rock', 'A buttress of the scarp juts out over the track here, black and dripping, and ravens nest on a ledge high up its face. They watch you pass. One of them says something about it, and the scarp says it back.', 0, 0, 'road', 0, 34, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-raven-rock', 'west', 'the-turf-stack-ruin', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-raven-rock', 'east', 'the-moor-gate', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-moor-gate', 'door', 'The Moor Gate', 'Two stone posts stand on the moor where a wall once crossed the track, the wall long gone back into the heather, the posts still upright with the iron of a gate hinge rusted into one of them. The track goes between them out of habit.', 0, 0, 'road', 0, 35, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moor-gate', 'west', 'the-raven-rock', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moor-gate', 'east', 'the-beck-gully', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-beck-gully', 'door', 'The Beck Gully', 'The track turns off the moor and goes down into the head of a gully cut into the scarp''s foot, where a beck has worn a way down through the rock. The sides close in. The sound of water starts somewhere below.', 0, 0, 'road', 0, 36, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-gully', 'west', 'the-moor-gate', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-gully', 'south', 'the-gully-steps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gully-steps', 'door', 'The Gully Steps', 'The way goes down the gully in a stair of wet rock and roots, the beck beside it falling in short white drops from pool to pool. Ferns grow out of every crack. It is cold in here and the light is green.', 0, 0, 'road', 0, 36, 16);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-steps', 'north', 'the-beck-gully', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-steps', 'south', 'the-beck-ford', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-beck-ford', 'door', 'The Beck Ford', 'The beck runs across the way in a broad shallow ford over flat stones, clear and quick and ice-cold, and everything that uses this gully stops here to drink. The mud at both edges is printed all over. The water does not care whose prints they are.', 0, 0, 'road', 0, 36, 17);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-ford', 'north', 'the-gully-steps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-ford', 'south', 'the-alder-gill', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-alder-gill', 'door', 'The Alder Gill', 'Alders crowd the bottom of the gully along the beck, their roots in the water, their trunks green with moss. The way goes along under them on a bank of stones. The gully opens out ahead, and the light grows.', 0, 0, 'road', 0, 36, 18);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-alder-gill', 'north', 'the-beck-ford', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-alder-gill', 'south', 'the-gully-mouth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gully-mouth', 'door', 'The Gully Mouth', 'The gully opens out onto the levels here, the beck spreading into a fan of stones and then losing itself in rushes. Behind, the scarp. Ahead, flat land to the edge of sight, green and wet and empty, and the smell of salt.', 0, 0, 'road', 0, 36, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-mouth', 'north', 'the-alder-gill', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-mouth', 'east', 'the-rush-levels', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-rush-levels', 'door', 'The Rush Levels', 'Flat wet grazing, gone to rush, the ground soft and tussocky underfoot, cut by drains you only see when you are at the edge of them. The way is a line of firmer ground that bends where the drains do. The sea is somewhere ahead.', 0, 0, 'road', 0, 37, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rush-levels', 'west', 'the-gully-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rush-levels', 'east', 'the-old-drain', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-old-drain', 'door', 'The Old Drain', 'A drain dug straight across the levels long ago to carry the water off to the sea, choked now with weed and reed and running slow and brown. A plank bridge crosses it, the planks gone soft. On the far bank the ground is wetter.', 0, 0, 'road', 0, 38, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-drain', 'west', 'the-rush-levels', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-drain', 'east', 'the-lapwing-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lapwing-ground', 'door', 'The Lapwing Ground', 'Open wet grass where plovers nest, and they go up all round you crying, tumbling in the air, diving at your head. They will follow you to the edge of their ground and leave you there. Beyond it, the reed begins.', 0, 0, 'road', 0, 39, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lapwing-ground', 'west', 'the-old-drain', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lapwing-ground', 'east', 'the-cattle-causey', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cattle-causey', 'door', 'The Cattle Causey', 'A causeway of packed stone and turf runs across the softest part of the levels, raised a foot above the wet, built for driving beasts across to the marsh grazing. It is narrow. Water stands on both sides of it.', 0, 0, 'road', 0, 40, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cattle-causey', 'west', 'the-lapwing-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cattle-causey', 'east', 'the-willow-holt-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-willow-holt-edge', 'door', 'The Willow Edge', 'Low willows grow in a ragged line across the levels where the fresh water meets the salt, grey-leaved and bent over by the wind off the sea. The causey goes through a gap in them. On the far side everything is reed.', 0, 0, 'road', 0, 41, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-willow-holt-edge', 'west', 'the-cattle-causey', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-willow-holt-edge', 'east', 'the-reed-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-reed-edge', 'door', 'The Reed Edge', 'The reed starts here, a wall of it, taller than you, rustling, the causey going into it like a road into a wood. Inside, you can see nothing but reed and sky. The sound of the sea is louder, and so is the sound of birds.', 0, 0, 'road', 0, 42, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-reed-edge', 'west', 'the-willow-holt-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-reed-edge', 'east', 'the-reed-path', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-reed-path', 'door', 'The Reed Path', 'A path through the reed, cut and kept by somebody once, now narrowing as the reed comes back in from both sides. The ground under it is wet. Things move in the reed beside you, and go still when you stop.', 0, 0, 'road', 0, 43, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-reed-path', 'west', 'the-reed-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-reed-path', 'east', 'the-bittern-pool', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bittern-pool', 'door', 'The Bittern Pool', 'The reed opens round a pool of brown water, still and deep-looking, with a fringe of floating weed. Something booms from the far side, low and hollow, like breath across the top of a jar. You cannot see it. It goes on.', 0, 0, 'road', 0, 44, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bittern-pool', 'west', 'the-reed-path', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bittern-pool', 'east', 'the-marsh-sill', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-marsh-sill', 'door', 'The Marsh Sill', 'A low sill of firm ground runs out into the marsh between the reed and the open water, the last solid ground before the causeys. The crossing''s channels are close now: the smell, the gulls, the sound of the tide working in the creeks.', 0, 0, 'road', 0, 45, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-sill', 'west', 'the-bittern-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-sill', 'east', 'the-causey-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-causey-foot', 'door', 'The Causey Foot', 'The sill ends at the foot of the crossing''s causeys, the old wooden ways laid across the marsh, and the path you came by joins them here. Behind you the reed, and the levels, and the scarp, a long way back. Ahead, the crossing.', 0, 0, 'road', 0, 46, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causey-foot', 'west', 'the-marsh-sill', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causey-foot', 'east', 'the-causey-end', NULL);
